WITH t AS(SELECT user_id FROM course_completions GROUP BY user_id HAVING COUNT(*)>=5 AND AVG(course_rating)>=4),c AS(SELECT *,LEAD(course_name)OVER(PARTITION BY user_id ORDER BY completion_date) n FROM course_completions WHERE user_id IN(SELECT user_id FROM t))SELECT course_name first_course,n second_course,COUNT(*) transition_count FROM c WHERE n IS NOT NULL GROUP BY 1,2 ORDER BY 3 DESC,1,2;